CREATE TABLE "fotos" ("id" TEXT NOT NULL, "url" TEXT NOT NULL, "publicId" TEXT NOT NULL, "categoria" TEXT, "liquidacionId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "fotos_pkey" PRIMARY KEY ("id"), CONSTRAINT "fotos_liquidacionId_fkey" FOREIGN KEY ("liquidacionId") REFERENCES "liquidaciones"("id") ON DELETE CASCADE ON UPDATE CASCADE); CREATE INDEX "fotos_liquidacionId_idx" ON "fotos"("liquidacionId");
